package com.vit.archds.controller;
import com.fasterxml.jackson.databind.*;import com.vit.archds.dto.ProjectDtos.*;import com.vit.archds.entity.Requirement;import com.vit.archds.service.ProjectService;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.util.*;
@RestController @RequestMapping("/api/projects/{projectId}") public class ResearchController {
 private final ProjectService projects; private final RestClient ai; private final ObjectMapper mapper;
 public ResearchController(ProjectService p,RestClient a,ObjectMapper m){projects=p;ai=a;mapper=m;}
 @PostMapping("/requirements/analyze") public JsonNode analyze(@PathVariable long projectId){Requirement r=projects.latestRequirement(projectId);try{Map<String,Object>b=new LinkedHashMap<>();b.put("project_name",r.getProject().getName());b.put("description",Objects.toString(r.getProject().getDescription(),""));b.put("functional_requirements",split(r.getFunctionalRequirements()));b.put("non_functional_requirements",split(r.getNonFunctionalRequirements()));b.put("constraints",split(r.getConstraints()));b.put("technology_preferences",split(r.getTechnologyPreferences()));b.put("expected_users",r.getExpectedUsers());b.put("budget",r.getBudget());Map<String,Integer> customWeights=mapper.readValue(r.getQualityWeightsJson(),Map.class);if(customWeights!=null&&!customWeights.isEmpty())b.put("quality_weights",customWeights);b.put("num_alternatives",5);b.put("max_iterations",5);return ai.post().uri("/api/v1/requirements/analyze").body(b).retrieve().body(JsonNode.class);}catch(Exception e){throw new IllegalStateException("Requirement analysis is temporarily unavailable");}}
 @PostMapping("/what-if") public JsonNode whatIf(@PathVariable long projectId,@RequestParam(defaultValue="10x") String users,@RequestParam(defaultValue="unchanged") String availability){return runScenario(projectId,"/api/v1/what-if?users="+users+"&availability="+availability);}
 @PostMapping("/stress-test") public JsonNode stress(@PathVariable long projectId,@RequestParam(defaultValue="10x traffic") String scenario){return runScenario(projectId,"/api/v1/stress-test?scenario="+java.net.URLEncoder.encode(scenario,java.nio.charset.StandardCharsets.UTF_8));}
 private JsonNode runScenario(long id,String uri){Requirement r=projects.latestRequirement(id);try{Map<String,Object>b=new LinkedHashMap<>();b.put("project_name",r.getProject().getName());b.put("description",Objects.toString(r.getProject().getDescription(),""));b.put("functional_requirements",split(r.getFunctionalRequirements()));b.put("non_functional_requirements",split(r.getNonFunctionalRequirements()));b.put("constraints",split(r.getConstraints()));b.put("technology_preferences",split(r.getTechnologyPreferences()));b.put("expected_users",r.getExpectedUsers());b.put("budget",r.getBudget());Map<String,Integer> customWeights=mapper.readValue(r.getQualityWeightsJson(),Map.class);if(customWeights!=null&&!customWeights.isEmpty())b.put("quality_weights",customWeights);b.put("num_alternatives",5);b.put("max_iterations",5);return ai.post().uri(uri).body(b).retrieve().body(JsonNode.class);}catch(Exception e){throw new IllegalStateException("Scenario analysis failed");}}
 private List<String> split(String s){if(s==null||s.isBlank())return List.of();return Arrays.stream(s.split("\\R|;")).map(String::trim).filter(x->!x.isBlank()).toList();}
}
